class Animal {}
class Dog extends Animal {
    void bark() { System.out.println("Woof!"); }
}
class Cat extends Animal {
    void meow() { System.out.println("Meow!"); }
}

Animal a = new Dog();

// 안전하지 않은 다운캐스팅
// Cat c = (Cat) a;  // ClassCastException!

// 안전한 다운캐스팅
if (a instanceof Dog) {
    Dog d = (Dog) a;
    d.bark();
}

// Java 16+ 패턴 매칭
if (a instanceof Dog d) {
    d.bark();  // 캐스팅 자동!
}
